  TransactionRow copyWith({
    int? id,
    TxType? type,
    Money? amount,
    int? accountId,
    Value<int?> toAccountId = const Value.absent(),
    Value<int?> categoryId = const Value.absent(),
    Value<int?> personId = const Value.absent(),
    DateTime? date,
    Value<String?> note = const Value.absent(),
